// Setup Script Otomatis Proyek BK SMA Muhammadiyah Singaparna
// Cara Pakai:
// 1. Simpan file ini di folder kosong (misal: C:\BK-MUDASPA\setup-project.js)
// 2. Buka Terminal / CMD di folder tersebut
// 3. Jalankan: node setup-project.js
// 4. Semua folder dan file proyek akan otomatis terbuat 100% lengkap!

const fs = require('fs');
